B.Oi=s(["\xb7 \uac00\uc785 \ud655\uc778, \ub85c\uadf8\uc778, \uacc4\uc815 \uad00\ub9ac","\xb7 \ucc98\ubc29\uc804 \uae00\uc790 \uc778\uc2dd\uacfc \uc57d \ub4f1\ub85d, \ubcf5\uc57d \uc77c\uc815\uacfc \uc54c\ub9bc \uc81c\uacf5","\xb7 \ub098\uc774, \uc784\uc2e0\xb7\uc218\uc720 \uc0c1\ud0dc, \ub4f1\ub85d\ud55c \uc57d\uc744 \ubc14\ud0d5\uc73c\ub85c \ud55c \ud568\uaed8\uba39\uae30 \uc8fc\uc758(DUR) \uc548\ub0b4","\xb7 \uc57d \uc124\uba85\uacfc AI \uc57d\uc0ac \uc0c1\ub2f4 \ub2f5\ubcc0 \uc81c\uacf5","\xb7 \uc57d \ub4dc\uc2dc\uae30 \uc804\ud6c4\uc758 \uc2ec\ubc15\uc218 \uae30\ub85d\uacfc \ubcc0\ud654 \ubcf4\uc5ec \ub4dc\ub9ac\uae30","\xb7 \uc774\uc6a9\uc790\uac00 \ucd08\ub300\ud588\uac70\ub098 \uc5f0\uacb0\uc744 \uc218\ub77d\ud55c \ubcf4\ud638\uc790\uc5d0\uac8c \ubcf5\uc57d \ud604\ud669 \ubcf4\uc5ec \ub4dc\ub9ac\uae30","\xb7 \ubb38\uc758 \uc751\ub300\uc640 \uc11c\ube44\uc2a4 \uc624\ub958 \uace0\uce58\uae30","\xb7 \ub9c8\ucf00\ud305 \uc815\ubcf4 \uc218\uc2e0\uc5d0 \ub3d9\uc758\ud55c \uacbd\uc6b0\uc5d0\ub9cc \uc0c8 \uae30\ub2a5\uacfc \uc18c\uc2dd \uc548\ub0b4"],t.s)
B.Jh=new A.d3("4. \uc774\uc6a9 \ubaa9\uc801",B.Oi)
B.Ql=s(["\xb7 \uac74\uac15 \uc0c1\ud0dc, \ubcd1\ub825, \uc54c\ub808\ub974\uae30, \uc784\uc2e0\xb7\uc218\uc720 \uc0c1\ud0dc, \ubcf5\uc6a9\ud558\ub294 \uc57d, \uc2ec\ubc15\uc218\ub294 \u300c\uac1c\uc778\uc815\ubcf4 \ubcf4\ud638\ubc95\u300d \uc81c23\uc870\uc758 \ubbfc\uac10\uc815\ubcf4\uc5d0 \ud574\ub2f9\ud569\ub2c8\ub2e4.","\xb7 \uac74\uac15\uc815\ubcf4 \ucc98\ub9ac\uc5d0 \ud544\uc694\ud55c \ubcc4\ub3c4 \ubbfc\uac10\uc815\ubcf4 \ub3d9\uc758\uc640 \ub3d9\uc758 \uae30\ub85d \ubcf4\uad00 \uc808\ucc28\ub294 \uc2e4\uc81c \uc0ac\uc6a9\uc790 \ub300\uc0c1 \uc6b4\uc601 \uc804\uc5d0 \ud655\uc815\xb7\uac80\uc99d\ud574\uc57c \ud569\ub2c8\ub2e4. \uc77c\ubc18 \uac1c\uc778\uc815\ubcf4 \ub3d9\uc758\ub9cc\uc73c\ub85c \ubcc4\ub3c4 \ub3d9\uc758\uac00 \uc644\ub8cc\ub418\uc5c8\ub2e4\uace0 \uac04\uc8fc\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.","\xb7 \ubbfc\uac10\uc815\ubcf4\ub294 \uc704 \ubaa9\uc801 \ubc16\uc73c\ub85c \uc4f0\uc9c0 \uc54a\uc73c\uba70, \uad11\uace0\ub098 \ud310\ub9e4\uc5d0 \uc4f0\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4."],t.s)
B.IY=new A.d3("5. \ubbfc\uac10\uc815\ubcf4(\uac74\uac15\uc815\ubcf4) \ucc98\ub9ac",B.Ql)
B.PQ=s(["\xb7 \uac1c\uc778\uc815\ubcf4\ub294 \ud68c\uc6d0 \ud0c8\ud1f4 \ub54c\uae4c\uc9c0 \ubcf4\uc720\ud558\uace0 \uc774\uc6a9\ud569\ub2c8\ub2e4.","\xb7 \ud0c8\ud1f4\ud558\uba74 \uacc4\uc815\uacfc \ud568\uaed8 \ub4f1\ub85d\ud55c \uc57d, \ubcf5\uc57d \uae30\ub85d, \uc2ec\ubc15 \uae30\ub85d, \ubcf4\ud638\uc790 \uc5f0\ub77d\ucc98\ub97c \uc0ad\uc81c\ud569\ub2c8\ub2e4. \uc11c\ubc84 \uae30\ub85d \uc0ad\uc81c\uc640 \ubcc4\ub3c4\ub85c \ubcf4\uad00 \uc911\uc778 \ubc31\uc5c5\uc758 \uc0ad\uc81c \uc808\ucc28\ub3c4 \uad00\ub9ac\ud574\uc57c \ud569\ub2c8\ub2e4.","\xb7 \uad00\uacc4 \ubc95\ub839\uc5d0 \ub530\ub77c \ub530\ub85c \ubcf4\uad00\ud574\uc57c \ud558\ub294 \uc815\ubcf4\uac00 \uc788\uc73c\uba74 \uadf8 \uae30\uac04 \ub3d9\uc548\ub9cc \ubd84\ub9ac\ud574 \ubcf4\uad00\ud569\ub2c8\ub2e4.","\xb7 \uc11c\ubc84 \ubc31\uc5c5\uc758 \ubcf4\uad00 \uae30\uac04\uacfc \uc0ad\uc81c \uc808\ucc28\ub294 \uc6b4\uc601 \uc804\uc5d0 \ud655\uc815\ud558\uc5ec \uc548\ub0b4\ud574\uc57c \ud569\ub2c8\ub2e4. \uc0c8 \ubc31\uc5c5\uc744 \ub9cc\ub4e4\uc5c8\ub2e4\ub294 \uc774\uc720\ub9cc\uc73c\ub85c \uc608\uc804 \ubc31\uc5c5\uc774 \uc790\ub3d9 \uc0ad\uc81c\ub418\ub294 \uac83\uc740 \uc544\ub2d9\ub2c8\ub2e4.","\xb7 \ub85c\uadf8\uc544\uc6c3\ud558\uba74 \ub85c\uadf8\uc778 \uc778\uc99d\uc815\ubcf4\uac00 \uc9c0\uc6cc\uc9d1\ub2c8\ub2e4. \uc774\uc804 \uc0c1\ub2f4\uacfc \uc800\uc7a5 \ub2f5\ubcc0\uc740 \ub85c\uadf8\uc544\uc6c3\ub9cc\uc73c\ub85c \ubaa8\ub450 \uc0ad\uc81c\ub418\ub294 \uac83\uc740 \uc544\ub2c8\uba70, \uc571\uc758 \uc0ad\uc81c \uae30\ub2a5\uc774\ub098 \uae30\uae30 \uc571 \ub370\uc774\ud130 \uc0ad\uc81c\ub85c \uad00\ub9ac\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4."],t.s)
B.Jd=new A.d3("6. \ubcf4\uc720 \uae30\uac04\uacfc \ud30c\uae30",B.PQ)
B.Oo=s(["\uc6b4\uc601\uc790\ub294 \uc774\uc6a9\uc790\uc758 \uac1c\uc778\uc815\ubcf4\ub97c \ub2e4\ub978 \uc0ac\ub78c\uc5d0\uac8c \ud314\uac70\ub098 \uc81c\uacf5\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4. \ub2e4\ub9cc \ub2e4\uc74c\uc758 \uacbd\uc6b0\ub294 \uc608\uc678\uc785\ub2c8\ub2e4.","\xb7 \uc774\uc6a9\uc790\uac00 \ubcf4\ud638\uc790\ub97c \ucd08\ub300\ud588\uac70\ub098 \ubcf4\ud638\uc790\uc758 \uc5f0\uacb0 \uc694\uccad\uc744 \uc218\ub77d\ud55c \uacbd\uc6b0: \uadf8 \ubcf4\ud638\uc790\uc5d0\uac8c \ubcf5\uc57d \ud604\ud669\uacfc \uc2ec\ubc15 \uae30\ub85d\uc744 \ubcf4\uc5ec \ub4dc\ub9bd\ub2c8\ub2e4.","\xb7 \ubc95\ub960\uc5d0 \ud2b9\ubcc4\ud55c \uaddc\uc815\uc774 \uc788\uac70\ub098, \uc218\uc0ac\uae30\uad00\uc774 \ubc95\uc5d0 \uc815\ud55c \uc808\ucc28\uc5d0 \ub530\ub77c \uc694\uad6c\ud558\ub294 \uacbd\uc6b0"],t.s)
B.Ji=new A.d3("7. \ub2e4\ub978 \uc0ac\ub78c\uc5d0\uac8c \uc81c\uacf5",B.Oo)
B.Pp=s(["\uc11c\ube44\uc2a4\ub97c \uc81c\uacf5\ud558\ub824\uace0 \ub2e4\uc74c \ud68c\uc0ac\uc5d0 \uc77c\ubd80 \ucc98\ub9ac\ub97c \ub9e1\uae41\ub2c8\ub2e4.","\xb7 \ub124\uc774\ubc84\ud074\ub77c\uc6b0\ub4dc (NAVER CLOVA OCR): \ucc98\ubc29\uc804 \uc0ac\uc9c4\uc758 \uae00\uc790 \uc77d\uae30 \u2014 \ucc98\ubc29\uc804 \uc0ac\uc9c4","\xb7 Google (Gemini API): AI \uc57d\uc0ac \uc0c1\ub2f4 \ub2f5\ubcc0 \ub9cc\ub4e4\uae30 \u2014 \uc9c8\ubb38 \ub0b4\uc6a9, \uc9c8\ubb38\uacfc \uad00\ub828\ub41c \uc57d\uc758 \uacf5\uc2dd \uc815\ubcf4\uc640 \ud568\uaed8\uba39\uae30 \uc8fc\uc758 \uacb0\uacfc, \uad00\ub828 \uc9c8\ud658\xb7\uacfc\uac70\ub825\xb7\uc54c\ub808\ub974\uae30\xb7\ud761\uc5f0\xb7\uc74c\uc8fc \uc815\ubcf4\uc640 \ucd5c\uadfc \ub300\ud654","\xb7 Render: \uc11c\ubc84 \ud638\uc2a4\ud305 \u2014 \uc11c\ubc84\uc5d0\uc11c \ucc98\ub9ac\ud558\ub294 \ud68c\uc6d0\xb7\uac74\uac15\xb7\uc57d\xb7\ubcf5\uc57d\xb7\uc2ec\ubc15 \uc815\ubcf4","\xb7 \ud604\uc7ac \uc6b4\uc601 DB\ub294 Render\uc758 SQLite\uc785\ub2c8\ub2e4. Neon DB \uc774\uc804\uc744 \uc900\ube44\ud558\uace0 \uc788\uc73c\uba70, \uc2e4\uc81c \uc804\ud658 \uc2dc \ubcf4\uad00 \uc5c5\uccb4\uc640 \uc9c0\uc5ed \uc548\ub0b4\ub97c \uac31\uc2e0\ud569\ub2c8\ub2e4.","\uc57d \uc815\ubcf4\ub294 \uc2dd\uc57d\ucc98 \uacf5\uacf5\ub370\uc774\ud130\ud3ec\ud138(e\uc57d\uc740\uc694, \uc758\uc57d\ud488 \ud5c8\uac00\uc815\ubcf4, DUR \uc815\ubcf4)\uc5d0\uc11c \uc57d \uc774\ub984\uacfc \ucf54\ub4dc\ub85c \uc870\ud68c\ud558\uba70, \uc774\ub54c \uc774\uc6a9\uc790\ub97c \uc54c\uc544\ubcfc \uc218 \uc788\ub294 \uc815\ubcf4\ub294 \ubcf4\ub0b4\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.","\ub9e1\uae34 \uacf3\uc774 \uc815\ubcf4\ub97c \ub450\ub294 \uae30\uac04\uc740 \uc704\ud0c1 \uacc4\uc57d\uacfc \uac01 \ud68c\uc0ac\uc758 \uc815\ucc45\uc744 \ub530\ub985\ub2c8\ub2e4."],t.s)
B.IX=new A.d3("8. \ucc98\ub9ac\ub97c \ub9e1\uae30\ub294 \uacf3(\uc704\ud0c1)",B.Pp)
B.OD=s(["Google\uacfc Render\ub294 \uc774\uc6a9\uc790\uc758 \uc815\ubcf4\ub97c \uad6d\uc678\uc5d0\uc11c \ucc98\ub9ac\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","\xb7 \uc774\uc804\ubc1b\ub294 \uacf3: Google, Render","\xb7 \uc774\uc804 \uc2dc\uae30\uc640 \ubc29\ubc95: \uc11c\ube44\uc2a4\ub97c \uc4f0\uc2e4 \ub54c \uc778\ud130\ub137\uc73c\ub85c \uc804\uc1a1","\xb7 \uc774\uc804 \ud56d\ubaa9\uacfc \ubaa9\uc801: \uc704 8\ubc88\uacfc \uac19\uc2b5\ub2c8\ub2e4","\xb7 \uc5c5\uccb4\ubcc4 \ubcf4\uc720 \uae30\uac04\uacfc \uc774\uc804\uc758 \ubc95\uc801 \uadfc\uac70\xb7\ub3d9\uc758 \uc808\ucc28\ub294 \uc6b4\uc601 \uc804\uc5d0 \ud655\uc778\ud558\uc5ec \uad6c\uccb4\uc801\uc73c\ub85c \uc548\ub0b4\ud574\uc57c \ud569\ub2c8\ub2e4.","\uad6d\uc678 \uc774\uc804\uc744 \uc6d0\ud558\uc9c0 \uc54a\uc73c\uc2dc\uba74 AI \uc57d\uc0ac \uc0c1\ub2f4\uc744 \uc4f0\uc9c0 \uc54a\uac70\ub098 \ud0c8\ud1f4\ud558\uc2e4 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ub2e4\ub9cc \uc11c\ubc84 \ud638\uc2a4\ud305\uc740 \uc11c\ube44\uc2a4 \uc81c\uacf5\uc5d0 \uaf2d \ud544\uc694\ud558\uc5ec, \uac70\ubd80\ud558\uc2dc\uba74 \uc11c\ube44\uc2a4\ub97c \uc4f8 \uc218 \uc5c6\uc2b5\ub2c8\ub2e4."],t.s)
B.IV=new A.d3("9. \uad6d\uc678 \uc774\uc804",B.OD)
B.OS=s(['\xb7 \uc5b8\uc81c\ub4e0 "\ub0b4 \uc815\ubcf4"\uc5d0\uc11c \ub0b4 \uc815\ubcf4\ub97c \ubcf4\uace0 "\uc218\uc815"\uc73c\ub85c \ubc14\ub85c\uc7a1\uc744 \uc218 \uc788\uc2b5\ub2c8\ub2e4.','\xb7 "\ub0b4 \uc815\ubcf4" \u2192 "\uacc4\uc815 \uad00\ub9ac" \u2192 "\uadf8\ub9cc\ub450\uae30"\ub85c \ud0c8\ud1f4\ud558\uba74 \uc815\ubcf4\uac00 \uc9c0\uc6cc\uc9d1\ub2c8\ub2e4.',"\xb7 \uc5f4\ub78c, \ucc98\ub9ac \uc815\uc9c0, \ub3d9\uc758 \ucca0\ud68c, \ubcf4\ud638\uc790 \uacf5\uc720 \uc911\ub2e8\uc740 \ub0b4 \uc815\ubcf4 \u2192 \ub3c4\uc6c0\ub9d0 \uc5d0\uc11c \uc694\uccad\ud558\uc2dc\uba74 \uc9c0\uccb4 \uc5c6\uc774 \ucc98\ub9ac\ud569\ub2c8\ub2e4.","\xb7 \ub9c8\ucf00\ud305 \uc815\ubcf4 \uc218\uc2e0 \ub3d9\uc758\ub294 \uc5b8\uc81c\ub4e0 \ucca0\ud68c\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","\xb7 \uac00\uc871 \ub4f1 \ub300\ub9ac\uc778\ub3c4 \uc704\uc784\uc744 \ubc1b\uc544 \uad8c\ub9ac\ub97c \ud589\uc0ac\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4."],t.s)
B.J1=new A.d3("10. \uc774\uc6a9\uc790\uc758 \uad8c\ub9ac\uc640 \ud589\uc0ac \ubc29\ubc95",B.OS)
B.Nw=s(["\xb7 \uce74\uba54\ub77c: \ucc98\ubc29\uc804 \uc0ac\uc9c4 \ucc0d\uae30","\xb7 \uc0ac\uc9c4(\uc568\ubc94): \uc774\ubbf8 \ucc0d\uc5b4 \ub454 \ucc98\ubc29\uc804 \uc0ac\uc9c4 \uace0\ub974\uae30","\xb7 \ube14\ub8e8\ud22c\uc2a4(\uae30\uae30\uc5d0 \ub530\ub77c \uc704\uce58 \uad8c\ud55c \ud3ec\ud568): \ud3f4\ub77c \uc2ec\ubc15 \uc13c\uc11c \ucc3e\uae30\uc640 \uc5f0\uacb0","\xb7 \uc54c\ub9bc: \ubcf5\uc57d \uc2dc\uac04 \uc54c\ub824 \ub4dc\ub9ac\uae30","\uad8c\ud55c\uc744 \ud5c8\uc6a9\ud558\uc9c0 \uc54a\uc544\ub3c4 \uadf8 \uad8c\ud55c\uc774 \ud544\uc694\ud55c \uae30\ub2a5 \ub9d0\uace0\ub294 \uc4f8 \uc218 \uc788\uc2b5\ub2c8\ub2e4."],t.s)
B.Jc=new A.d3("11. \uc804\ud654\uae30 \uad8c\ud55c",B.Nw)
B.NB=s(["\xb7 \ube44\ubc00\ubc88\ud638\ub97c \uc54c\uc544\ubcfc \uc218 \uc5c6\uac8c \ubc14\uafd4 \uc800\uc7a5","\xb7 \uac1c\uc778\uc815\ubcf4\ub97c \ub2e4\ub8f0 \uc218 \uc788\ub294 \uc0ac\ub78c\uc744 \ucd5c\uc18c\ud55c\uc73c\ub85c \uc81c\ud55c","\xb7 \uc778\ud130\ub137\uc73c\ub85c \uc8fc\uace0\ubc1b\ub294 \uc815\ubcf4\uc758 \uc554\ud638\ud654 \uc804\uc1a1","\xb7 \ube44\ubc00\uac12\xb7\ucc98\ubc29\uc804 \uc6d0\ubb38\xb7\uac74\uac15\uc815\ubcf4\ub97c \uc624\ub958 \ub85c\uadf8\uc5d0 \ub0a8\uae30\uc9c0 \uc54a\ub3c4\ub85d \uad00\ub9ac"],t.s)
